namespace PCOptimizer.Core;

internal static class AdditionalExecutableTweaks
{
    private const string Explorer = @"Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced";
    private const string Delivery = @"Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager";
    private const string PrivacySource = "https://github.com/farag2/Sophia-Script-for-Windows/blob/3a24646741c56be258f326d63523f105a3fec467/src/Sophia_Script_for_Windows_11/Module/Sophia.psm1";
    private const string ExplorerSource = "https://github.com/farag2/Sophia-Script-for-Windows/blob/3a24646741c56be258f326d63523f105a3fec467/src/Sophia_Script_for_Windows_11/Module/Sophia.psm1";
    private const string TaskbarSource = "https://github.com/farag2/Sophia-Script-for-Windows/blob/3a24646741c56be258f326d63523f105a3fec467/src/Sophia_Script_for_Windows_11/Module/Sophia.psm1";
    private const string InputSource = "https://learn.microsoft.com/windows/win32/api/winuser/nf-winuser-systemparametersinfoa";
    private static RegistryTweakTarget D(string id, string path, string name, uint number, bool machine = false) =>
        new(id, path, name, new(true, "DWord", number.ToString(System.Globalization.CultureInfo.InvariantCulture)), machine);
    private static ExecutableTweak Setting(string id, string name, string category, string benefit, string risk,
        string source, params RegistryTweakTarget[] targets) => new(id, name, category, benefit, risk,
            targets.Any(t => t.Machine) ? "Puede requerir reinicio manual. Verifica la opción efectiva en Windows después de aplicar." :
            "Puede requerir reabrir la aplicación o cerrar y volver a iniciar sesión. No se reinicia Explorer automáticamente.", source, targets);
    private static ExecutableTweak Hotkey(string id, string name, string path) => Setting(id, name, "Entrada",
        "Desactiva únicamente la combinación de teclas que invoca esta función. Conserva las demás banderas y el estado de la función de accesibilidad.",
        "El atajo dejará de estar disponible, también fuera del juego. Solo se aplica si Windows expone las banderas actuales; no se inventa una configuración por defecto.",
        InputSource, new RegistryTweakTarget(id, path, "Flags", new(true, "String", "0"), ClearBits: 4));

    public static IReadOnlyList<ExecutableTweak> Items { get; } = Array.AsReadOnly(new[]
    {
        Hotkey("sticky-hotkey", "Evitar el aviso de Teclas especiales al pulsar Shift", @"Control Panel\Accessibility\StickyKeys"),
