            D("long-paths", @"SYSTEM\CurrentControlSet\Control\FileSystem", "LongPathsEnabled", 1, true)),
        Setting("ad-id", "Desactivar el identificador de publicidad", "Privacidad",
            "Desactiva el uso del identificador publicitario de Windows para tu usuario. Preferencia de privacidad sin mejora de FPS atribuida.",
