            D("search-history", @"Software\Microsoft\Windows\CurrentVersion\SearchSettings", "IsDeviceSearchHistoryEnabled", 0)),
        Setting("clipboard-history", "Desactivar historial del portapapeles", "Privacidad",
            "Desactiva la preferencia del historial que se abre con Windows + V; copiar y pegar normal sigue disponible.",
