        Setting("taskbar-search", "Ocultar búsqueda en la barra de tareas", "Personalización",
            "Oculta el cuadro/botón de búsqueda. Windows + S y la búsqueda de Inicio siguen disponibles.",
            "Se pierde ese acceso visible; no se detiene Windows Search ni se elimina el indexador.", TaskbarSource,
            D("taskbar-search", @"Software\Microsoft\Windows\CurrentVersion\Search", "SearchboxTaskbarMode", 0)),
        Setting("end-task", "Habilitar Finalizar tarea desde la barra", "Personalización",
