            "https://learn.microsoft.com/windows/apps/get-started/enable-your-device-for-development",
            D("end-task", Explorer + @"\TaskbarDeveloperSettings", "TaskbarEndTask", 1)) with { MinimumWindowsBuild = 22631, RiskOverride = TweakRisk.Standard },
        Setting("clock-seconds", "Mostrar segundos en el reloj de la barra", "Personalización",
            "Activa los segundos del reloj en compilaciones compatibles. Es personalización, no una optimización.",
            "Actualizar el reloj con más frecuencia puede aumentar consumo, especialmente en laptops.", TaskbarSource,
            D("clock-seconds", Explorer, "ShowSecondsInSystemClock", 1)) with { MinimumWindowsBuild = 22631 },
        Setting("numlock", "Activar Bloq Num al iniciar sesión", "Entrada",
            "Guarda InitialKeyboardIndicators=2 para el inicio de sesión del usuario. No modifica firmware ni la cuenta de la pantalla de bienvenida.",
